#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# The Sheet's one-time setup (docs/sheet.md, "Setup Lisul does once"). Run from the repo root:
#   bash tools/sheet-setup.sh
# Public values (project URL, anon key, owner email) are remembered in .env (gitignored) so a
# re-run skips what's done. The Google client secret is never written to disk.

# copy TEXT puts TEXT on the clipboard (macOS pbcopy), or prints it if there's no clipboard.
copy() {
  if command -v pbcopy >/dev/null 2>&1; then printf '%s' "$1" | pbcopy; printf '  %s✓ copied to your clipboard%s\n' "$GREEN" "$RESET"
  else note "Copy this: $1"; fi
}

# api PATH prints the HTTP status of a public Supabase request.
api_status() {
  curl -s -o /dev/null -w '%{http_code}' "$SHEET_SUPABASE_URL$1" -H "apikey: $SHEET_ANON_KEY"
}

run_wizard() {

TOTAL_STAGES=9
ENV_FILE=.env
[[ -f src/site.mjs && -f supabase/schema.sql ]] || { warn "Run this from the lisul-elvi-site repo root (the sheet branch)."; exit 1; }

banner "The Sheet: connect Supabase and Google Calendar"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Supabase: create the project"
say "Supabase stores your tasks. The free plan is enough."
open_url "https://supabase.com/dashboard/projects"
step "Sign in (GitHub sign-in is fine), then click 'New project'."
step "Name it 'the-sheet'. Pick any database password (you won't need it here) and the region"
step "closest to you (East US). Click 'Create new project' and wait about a minute."
step "Then open the project's 'Connect' button (top of the project home), or"
step "Project Settings → Data API, and copy the Project URL (https://….supabase.co)."
while :; do
  ask SHEET_SUPABASE_URL "Paste the Project URL:"
  SHEET_SUPABASE_URL="${SHEET_SUPABASE_URL%/}"
  [[ "$SHEET_SUPABASE_URL" =~ ^https://[a-z0-9]+\.supabase\.co$ ]] && break
  warn "That should look like https://abcdefghijkl.supabase.co. Try again."
done
write_env SHEET_SUPABASE_URL "$SHEET_SUPABASE_URL"
SHEET_REF="${SHEET_SUPABASE_URL#https://}"; SHEET_REF="${SHEET_REF%%.*}"
pause "Press Enter for the key"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Supabase: copy the public key"
say "The browser uses this key to talk to Supabase. It's public by design: row-level"
say "security decides what anyone can see."
open_url "https://supabase.com/dashboard/project/$SHEET_REF/settings/api-keys"
step "Copy the 'anon public' key (under Legacy API keys, starts eyJ…)"
step "or the 'Publishable key' (starts sb_publishable_…). Either works."
note "Never the service_role or secret key: those bypass all security."
while :; do
  ask SHEET_ANON_KEY "Paste the anon or publishable key:"
  [[ "$SHEET_ANON_KEY" =~ ^(eyJ|sb_publishable_) ]] && break
  warn "That doesn't look like an anon (eyJ…) or publishable (sb_publishable_…) key."
done
write_env SHEET_ANON_KEY "$SHEET_ANON_KEY"
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Supabase: create the tables"
say "Only one Google account may open /plan: the one you'll plan with."
ask SHEET_OWNER_EMAIL "Your Google account email (the one with your calendar):"
write_env SHEET_OWNER_EMAIL "$SHEET_OWNER_EMAIL"
SQL_FILE=$(mktemp "${TMPDIR:-/tmp}/sheet-schema.XXXXXX")
sed "s/you@example\.com/${SHEET_OWNER_EMAIL//\//\\/}/" supabase/schema.sql > "$SQL_FILE"
copy "$(cat "$SQL_FILE")"
open_url "https://supabase.com/dashboard/project/$SHEET_REF/sql/new"
step "Paste into the SQL editor (⌘V) and click 'Run'."
step "If it warns about 'destructive operations' (the drop-if-exists lines), confirm: it's safe."
note "If the clipboard didn't work, the filled-in file is $SQL_FILE"
while :; do
  pause "Press Enter once it says 'Success'"
  status=$(api_status /rest/v1/public_now)
  [[ "$status" == 200 ]] && { printf '  %s✓ the public view answers%s\n' "$GREEN" "$RESET"; break; }
  warn "public_now answered $status, not 200. Check the SQL editor for an error and run it again."
  confirm "Skip this check and go on anyway?" && break
done
rm -f "$SQL_FILE"

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Google Cloud: create a project and its sign-in screen"
say "Google needs an 'app' so /plan can ask for calendar access. Only you will use it."
open_url "https://console.cloud.google.com/projectcreate"
step "Project name: 'The Sheet'. Click 'Create', then select it in the top bar."
pause "Press Enter once the new project is selected"
open_url "https://console.cloud.google.com/auth/overview"
step "Click 'Get started'. App name: The Sheet. Support email: yours. Next."
step "Audience: External. Next. Contact email: yours. Agree, then 'Create'."
pause "Press Enter when the sign-in screen is created"

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Google Cloud: turn on the Calendar API"
open_url "https://console.cloud.google.com/apis/library/calendar-json.googleapis.com"
step "Check the top bar shows 'The Sheet', then click 'Enable'."
pause "Press Enter once it says 'API enabled'"

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Google Cloud: calendar permissions and you as a tester"
open_url "https://console.cloud.google.com/auth/scopes"
step "Data Access → 'Add or remove scopes'. At the bottom, 'Manually add scopes', paste:"
copy "https://www.googleapis.com/auth/calendar.app.created,https://www.googleapis.com/auth/calendar.events.readonly"
note "https://www.googleapis.com/auth/calendar.app.created"
note "https://www.googleapis.com/auth/calendar.events.readonly"
step "Click 'Add to table', then 'Update', then 'Save' at the bottom of the page."
pause "Press Enter when both scopes are saved"
open_url "https://console.cloud.google.com/auth/audience"
step "Under 'Test users', click 'Add users', add $SHEET_OWNER_EMAIL, and save."
note "The app stays in 'Testing'; that's fine for one person. Google will show an"
note "'unverified app' screen the first time you sign in: click Continue."
pause "Press Enter when you're a test user"

# ── 7 ────────────────────────────────────────────────────────────────────
stage "Google Cloud: the sign-in client"
open_url "https://console.cloud.google.com/auth/clients"
step "'Create client'. Application type: Web application. Name: The Sheet."
step "Under 'Authorized redirect URIs', click 'Add URI' and paste (now on your clipboard):"
copy "$SHEET_SUPABASE_URL/auth/v1/callback"
note "$SHEET_SUPABASE_URL/auth/v1/callback"
step "Click 'Create'. A dialog shows the Client ID and Client secret: keep it open."
ask GOOGLE_CLIENT_ID "Paste the Client ID (ends .apps.googleusercontent.com):"
ask_secret GOOGLE_CLIENT_SECRET "Paste the Client secret (hidden; it's only used in the next stage):"

# ── 8 ────────────────────────────────────────────────────────────────────
stage "Supabase: turn on Google sign-in"
open_url "https://supabase.com/dashboard/project/$SHEET_REF/auth/providers"
step "Open 'Google', switch 'Enable Sign in with Google' on."
copy "$GOOGLE_CLIENT_ID"
step "Paste the Client ID (on your clipboard now) into 'Client IDs'."
pause "Press Enter to put the Client secret on the clipboard"
copy "$GOOGLE_CLIENT_SECRET"
step "Paste it into 'Client Secret (for OAuth)', then click 'Save'."
pause "Press Enter once saved"
printf '' | pbcopy 2>/dev/null || true
unset GOOGLE_CLIENT_SECRET
open_url "https://supabase.com/dashboard/project/$SHEET_REF/auth/url-configuration"
step "Site URL: https://www.lisul-elvi.com"
step "Redirect URLs → 'Add URL', add both, then save:"
note "https://www.lisul-elvi.com/plan/"
note "http://localhost:4321/plan/"
copy "https://www.lisul-elvi.com/plan/"
while :; do
  pause "Press Enter when both are saved"
  if curl -s "$SHEET_SUPABASE_URL/auth/v1/settings" -H "apikey: $SHEET_ANON_KEY" | grep -q '"google":true'; then
    printf '  %s✓ Supabase reports Google sign-in on%s\n' "$GREEN" "$RESET"; break
  fi
  warn "Supabase doesn't report Google as enabled yet. Check the provider was saved."
  confirm "Skip this check and go on anyway?" && break
done

# ── 9 ────────────────────────────────────────────────────────────────────
stage "Connect the site"
say "Writing the project URL and key into SHEET in src/site.mjs."
SHEET_SUPABASE_URL="$SHEET_SUPABASE_URL" SHEET_ANON_KEY="$SHEET_ANON_KEY" node --input-type=module -e '
  import { readFileSync, writeFileSync } from "node:fs";
  const f = "src/site.mjs";
  const src = readFileSync(f, "utf8")
    .replace(/supabaseUrl: "[^"]*"/, `supabaseUrl: "${process.env.SHEET_SUPABASE_URL}"`)
    .replace(/anonKey: "[^"]*"/, `anonKey: "${process.env.SHEET_ANON_KEY}"`);
  writeFileSync(f, src);
'
git --no-pager diff --stat -- src/site.mjs
if confirm "Commit this to the current branch?"; then
  git add src/site.mjs && git commit -q -m "Connect The Sheet to its Supabase project" && printf '  %s✓ committed%s\n' "$GREEN" "$RESET"
else
  SKIPPED+=("commit src/site.mjs")
fi
say ""
say "Try it locally:  npm run dev   then open http://localhost:4321/plan/ and sign in."
say "Allow calendar access; 'Plan today' then creates a 'Time blocks' calendar on first use."
pause "Press Enter to finish"

finish
}

run_wizard "$@"; exit
